from pathlib import Path
from lesson_authoring import entry as E
H=[['拉丁 fluere；分词 fluēns、fluxus；相关 fluvius','流动；流动的；河流']]
IN=H+[['拉丁 īnfluere → 中世纪拉丁 īnfluentia','流入；古时所谓星体流来的作用力'],['古法语 influence → 中古英语 → influence','影响力；后来作动词“影响”']]
FL=H+[['拉丁 fluēns → 英语 fluent','流动的 → 话语流畅的']]
FD=H+[['拉丁 fluidus → 英语 fluid','能流动的；流体；灵活流畅的']]
FT=H+[['拉丁 fluctus → fluctuāre / fluctuātus','波浪 → 起伏、摇摆'],['英语 fluctuate','波动；变化不定']]
def D(h,a,b):return h+[[a,b]]
W=[
E('influence','/ˈɪnfluəns/','影响；影响力；有影响的人或事','一种力量不必直接命令你，却慢慢改变你怎么想、怎么做，像水流渗进来改变周围。','拉丁 in- 向里 + fluere 流，形成 īnfluere、īnfluentia；经法语进入英语。',IN,'早期英语含占星术中星体力量作用于人的观念，那是词义历史，不是科学事实。现代常说人、环境、思想对结果的影响。','influence a decision；have an influence on；under the influence of。','control 强调掌控结果；influence 只要求产生影响，不保证对方照你的意思行动。',('Her teacher had a lasting influence on her choice of career.','老师对她的职业选择产生了持久影响。'),('The weather may influence our plans.','天气可能影响我们的计划。'),sources=['https://www.etymonline.com/word/influence']),
E('fluid','/ˈfluːɪd/','流体；液体；流动的；灵活、未固定的','倒进不同容器会改变形状，这就是直观的 fluid；安排或动作不僵硬，也能借这个画面来讲。','借拉丁 fluidus，来自 fluere“流动”。',FD,'物理里的 fluid 包括能流动的液体和气体；日常语境也常专指液体。a fluid situation 则表示局势还会变，没有定死。','a fluid situation；fluid movement；body fluids。','liquid 是液体；fluid 在物理里范围更宽，空气也属于流体。',('Air is a fluid, even though it is not a liquid.','空气是流体，尽管它不是液体。'),('Our plans are still fluid, so the date may change.','我们的计划还没定死，日期可能改变。'),sources=['https://en.wiktionary.org/wiki/fluid#English']),
E('flush','/flʌʃ/','冲洗；脸红；齐平；同花〔牌类〕','一股水涌过去可以冲洗，血色涌到脸上可以让人脸红；但这个拼写还装着几条不同的历史线。','冲动、冲洗义接中古英语 flusshen，远源未定；牌类“同花”可能接法语 flus、拉丁 fluxus。本页只把后一关系当可能来源。',[['中古英语 flusshen〔更早来源未定〕','突然冲出、迅速移动'],['英语 flush 的常用动词及相关义','冲洗；脸红；涌现'],['另支假说：法语 flus / flux → 牌类 flush','一套同花牌；与拉丁流动词族可能相关']],'flush the toilet 是冲厕所；flush with the wall 是与墙齐平；a flush 在扑克里是同花。它们不能全由“水流”机械推出来。','flush with；flush the toilet；a flush of colour。','blush 更常说因情绪羞红脸；flush 也可由热、活动等引起。flash 是闪光，别混看。',('Please flush the toilet after use.','使用后请冲厕所。'),('The shelf should sit flush with the wall.','搁板应与墙面齐平。'),('She won the hand with a flush.','她凭一手同花赢下了这一局。'),sources=['https://www.etymonline.com/word/flush']),
E('influx','/ˈɪnflʌks/','涌入；流入','原来外面的东西成批进入，像一股水穿过入口，带来数量上的明显增加。','拉丁 in- 向里 + fluxus 流动，接 īnfluere 的名词 īnflūxus。',[H[0],['拉丁 īnfluere → īnflūxus','流入 → 流入的过程'],['英语 influx','大量涌入']],'常说人口、游客、资金或信息的流入。通常用 an influx of，强调一波明显增加，不是普通一人进门。','an influx of visitors；an influx of information。','influence 主要是影响；influx 是流入，两者同接“向里流”，现代重点却不同。',('The town prepared for an influx of summer visitors.','小镇为夏季游客的大量涌入作了准备。'),('The team struggled to process the sudden influx of data.','团队很难及时处理突然涌入的大量数据。'),sources=['https://www.etymonline.com/word/influx']),
E('flux','/flʌks/','流动；不断变化；通量；助焊剂','它保留了流动、不停转移的画面；说局势 in flux，就是各部分还在移动，尚未定形。','古法语 flux 来自拉丁 fluxus“流动”，与 fluere 相接。',[H[0],['拉丁 fluxus → 古法语 flux → 英语 flux','流动 → 流动、变化及专门用语']],'日常最常见 in flux。物理里的通量关心某种量穿过表面的情况，具体定义随对象；焊接里的 flux 是帮助处理表面氧化物、促进焊接的助焊剂。','in a state of flux；magnetic flux；soldering flux。','flow 是普通流动；flux 常见于正式表达或专门术语，不能在所有句子里替换 flow。',('The organisation is in a state of flux after the merger.','合并后，组织结构仍在不断变化。'),('The technician applied flux before soldering the joint.','技术人员在焊接接头前涂了助焊剂。'),sources=['https://www.etymonline.com/word/flux']),
E('fluent','/ˈfluːənt/','语言流利的；表达流畅的','说话像顺畅流水，不总是卡住、重新起头；重点是能自然连续地表达。','拉丁 fluēns 是 fluere 的现在分词，原指流动的，英语发展为语言流利。',FL,'be fluent in a language 表示能流畅使用这种语言，并不等于每个专业词都懂、永不犯错。也可说动作或表达熟练顺畅。','fluent in English；a fluent speaker。','fluent 强调顺畅运用；accurate 强调正确，流利与准确相关但不是同一指标。',('She is fluent in both Spanish and English.','她能流利地使用西班牙语和英语。'),('His answer was fluent, but it contained a few errors.','他的回答很流畅，但有几处错误。'),sources=['https://www.etymonline.com/word/fluent']),
E('affluent','/ˈæfluənt/','富裕的；财力充足的','资源不断往这里流，生活因而宽裕；这股流入的画面成了财富充足的说法。','拉丁 ad- 朝向 + fluere → affluere，分词 affluēns 经法语 affluent 传入。',[H[0],['拉丁 affluere → affluēns → 法语 affluent','流向、充满 → 供应充足的'],['英语 affluent','富裕的；另有支流等旧义']],'常修饰人群、地区、社会，语气较正式。不是“英语说得很流利”，不能和 fluent 混看。','an affluent neighbourhood；affluent consumers。','wealthy 和 affluent 都可说富裕；affluent 常突出生活条件、资源供应宽裕。',('The shop mainly serves an affluent neighbourhood.','这家商店主要服务一个富裕社区。'),('The survey compares spending habits across affluent and less affluent households.','调查比较了富裕家庭与较不富裕家庭的消费习惯。'),sources=['https://www.etymonline.com/word/affluent']),
E('confluence','英 /ˈkɒnfluəns/；美 /ˈkɑːnfluəns/','河流交汇；汇合处；多种因素的汇合','两条河在同一处汇成一股；把河水换成人、想法或条件，就得到抽象的“汇聚”。','后期拉丁 cōnfluentia，接 con- 一起 + fluere 流。',[H[0],['拉丁 cōnfluere → cōnfluentia','一起流 → 汇流'],['中古英语 → confluence','汇合；汇合处']],'常用 at the confluence of 两条河，也可说 a confluence of factors。不是其中一个因素单独造成结果，而是多个条件相遇。','the confluence of two rivers；a confluence of events。','influx 是往里来；confluence 是多路汇到一起，强调交会。',('The city grew at the confluence of two rivers.','这座城市在两条河流的交汇处发展起来。'),('A confluence of events made the project possible.','多件事情碰在一起，使这个项目成为可能。'),sources=['https://en.wiktionary.org/wiki/confluence#English']),
E('fluency','/ˈfluːənsi/','流利程度；流畅性；熟练运用能力','把 fluent 的状态当作一项能力来看：说、读或处理事情时，能不能顺畅地进行。','有资料接后期拉丁 fluentia，也有词源分析为英语 fluent + -cy；共同基础都是 fluere 的流动意象。',[H[0],['两种来源分析：后期拉丁 fluentia；或英语 fluent + -cy','流动状态；或流利这一性质'],['英语 fluency','流利；流畅性']],'语言学习中常谈 speaking fluency；数字、技术等领域也可比喻熟练运用。它不只等于说话快，过快而混乱也不算好表达。','fluency in a language；improve fluency；reading fluency。','fluency 是顺畅程度；vocabulary 是词汇储备，两者互相帮助但不能等同。',('Regular conversation helped improve her fluency.','经常交谈帮助她提高了流利程度。'),('The activity develops fluency with basic number facts.','这项活动培养熟练运用基本数值关系的能力。'),sources=['https://en.wiktionary.org/wiki/fluency#English','https://www.etymonline.com/word/fluency']),
E('fluctuate','/ˈflʌktʃueɪt/','波动；起伏不定','水面有时升有时降，价格、温度和情绪也会这样上下变化。','拉丁 fluctus 波浪 → fluctuāre / fluctuātus，借入英语。',FT,'通常不及物：prices fluctuate。可以在两个值之间波动，也可围绕某个水平变化；并不要求每次起伏都有同样周期。','fluctuate between；fluctuate around；fluctuate widely。','increase 是增加；fluctuate 是来回变化，可能一段时间总体上涨，也可能总体下跌。',('Temperatures fluctuate widely in the desert.','沙漠里的温度变化很大。'),('Demand fluctuates throughout the year.','需求在一年中不断波动。'),sources=['https://www.etymonline.com/word/fluctuate']),
E('influencer','英 /ˈɪnfluənsə/；美 /ˈɪnfluənsər/','有影响力的人；社交媒体影响者、网红','他人的关注、选择或购买会受到这个人的内容影响，所以词名落在“能影响人”上。','influence + -er；先有一般影响者义，后来在营销与社交媒体中形成突出的专门用法。',D(IN,'英语 influence + -er → influencer','影响 → 产生影响的人'),'网络语境常说发布内容并影响受众的人，可能参与商业合作；不是所有内容创作者都有同样影响力，也不只按粉丝数定义。','a social media influencer；an influencer campaign。','celebrity 强调知名度；influencer 更突出对受众选择和行为的影响。',('The brand worked with a travel influencer to introduce the product.','品牌与一位旅行领域的社交媒体影响者合作介绍产品。'),('A teacher can be an important influencer in a child’s life.','老师可以是孩子生活中一个重要的影响者。'),sources=['https://www.etymonline.com/word/influencer']),
E('fluently','/ˈfluːəntli/','流利地；流畅地','句子连续出来，不必每说两三个词就停下搜寻表达；这个副词把顺畅放到说话动作上。','fluent + -ly；形容词变成副词。',D(FL,'英语 fluent + -ly → fluently','流利的 → 流利地'),'最常见 speak fluently，也可写 read 或 explain fluently。流利不代表完全没有口音。','speak fluently；read fluently；express oneself fluently。','quickly 只说速度快；fluently 强调表达顺畅，慢一点也可以很流利。',('He speaks French fluently but still has a noticeable accent.','他法语说得很流利，但仍有明显口音。'),('She read the passage fluently without stopping.','她流畅地读完了这段文字，没有停顿。'),sources=['https://en.wiktionary.org/wiki/fluently#English']),
E('fluidity','/fluːˈɪdəti/','流动性；流畅性；灵活可变的程度','材料容易流，动作容易衔接，角色容易变化，都可以说有 fluidity；共同点是不僵硬地卡住。','可能借法语 fluidité，也可能由英语 fluid + -ity 构成；两路都接 fluidus 词族。',[H[0],['拉丁 fluidus；法语 fluidité 或英语 fluid + -ity','流动的 → 流动性质'],['英语 fluidity','流动性；流畅性、可变性']],'技术中可指流动性质或黏度的倒数；日常也可说舞蹈动作的流畅、边界的灵活。必须看所讨论的对象。','the fluidity of movement；social fluidity；fluidity of form。','fluency 通常突出语言或技能运用；fluidity 更常说材料、动作和结构的流动可变。',('The dancer moved with remarkable fluidity.','舞者的动作格外流畅。'),('The novel explores the fluidity of personal identity.','小说探讨了个人身份如何流动变化。'),sources=['https://en.wiktionary.org/wiki/fluidity#English','https://www.etymonline.com/word/fluidity']),
E('fluctuation','/ˌflʌktʃuˈeɪʃən/','波动；起伏；波动幅度或一次变化','把 fluctuate 的上下起伏截下来观察，就得到一次 fluctuation，或一段时间里的 fluctuations。','拉丁 fluctuātiō 来自 fluctuāre，作为名词借入；现代对应 fluctuate + -ion。',[H[0],['拉丁 fluctus → fluctuāre → fluctuātiō','波浪 → 起伏 → 起伏的过程'],['英语 fluctuation','波动；起伏变化']],'常见 fluctuations in temperature、price fluctuations。既能说整体波动现象，也能数多次变化。','seasonal fluctuations；a fluctuation in；wide fluctuations。','trend 是较长期方向；fluctuations 是过程中的上下变化，短期波动未必改变趋势。',('The graph shows daily fluctuations in temperature.','图表显示了气温每天的波动。'),('Small fluctuations do not necessarily change the overall trend.','小幅波动不一定改变总体趋势。'),sources=['https://en.wiktionary.org/wiki/fluctuation#English']),
E('effluent','/ˈefluənt/','流出的；排放液；废水','从工厂或处理设施往外流的液体，把 e-/ex- 的“向外”直接带到词里。','拉丁 ex- 向外 + fluere 流 → effluere，分词 effluēns 经法语等路线进入英语。',[H[0],['拉丁 effluere → effluēns → 法语 effluent','向外流 → 流出的'],['英语 effluent','流出的；排放液、废水']],'现代名词常见于环保、工程文字。effluent 可能经过处理，是否有害取决于成分和处理程度，不能只凭词名判断。','industrial effluent；treated effluent；effluent discharge。','affluent 是富裕的；effluent 通常是流出的液体。开头元音改变后，意思差很大。',('The plant treats its effluent before discharge.','工厂在排放前处理废水。'),('The report measures the volume of effluent leaving the facility.','报告测量了从设施排出的液体体积。'),sources=['https://www.etymonline.com/word/effluent']),
E('fluvial','/ˈfluːviəl/','河流的；由河流作用形成的','不是泛泛有水，而是河水冲刷、搬运、沉积留下的地形和材料。','拉丁 fluvius 河流 + -ālis，形成 fluviālis，借入英语。',[H[0],['拉丁 fluvius → fluviālis','河流 → 河流相关的'],['英语 fluvial','河流的；河流作用形成的']],'常见地理、地质文献，如 fluvial deposits。既可描述河流环境，也可强调河流造成的结果。','fluvial erosion；fluvial deposits；a fluvial landscape。','marine 与海有关；fluvial 与河流有关，都是水环境却不是同一范围。',('The valley contains thick fluvial deposits.','山谷里有厚厚的河流沉积层。'),('Fluvial erosion gradually changed the shape of the valley.','河流侵蚀逐渐改变了山谷的形状。'),sources=['https://en.wiktionary.org/wiki/fluvial#English']),
E('fluidly','/ˈfluːɪdli/','流畅地；灵活连贯地','动作之间顺着接过去，没有突然卡住或硬拐弯，像液体一样连贯。','fluid + -ly；副词描述动作或变化的方式。',D(FD,'英语 fluid + -ly → fluidly','流畅、灵活的 → 流畅地'),'常用于动作、设计、转换或角色切换；描述说语言的流利程度时，fluently 通常更直接。','move fluidly；shift fluidly；transition fluidly。','fluently 常说语言表达；fluidly 常说动作与变化顺滑，不能看见 flu- 就机械换用。',('The skater moved fluidly across the ice.','滑冰者在冰面上流畅地移动。'),('The conversation shifted fluidly from work to travel.','谈话从工作自然顺畅地转到了旅行。'),sources=['https://en.wiktionary.org/wiki/fluidly#English']),
]
ROOT=dict(id='C0436',meaning='流动、涌流；话语、资源和影响也可以流动',core='FLU / FLUV / FLUX = FLOW',image='画一股水流：流进来是 influx，几路汇到一起是 confluence，排出去是 effluent。把水换成话语，顺畅流出就是 fluent；换成资源，充足流入便帮助理解 affluent。',intro='主干来自拉丁 fluere“流动”，相关词形有 fluēns、fluxus，以及 fluvius“河流”、fluctus“波浪”等。英文 flow 可以解释意思，但不能仅凭意思与字形相似，就把它当所有这些借词的直接祖先。',forms='in- 向里、con- 一起、ex-/e- 向外、ad-/af- 朝向；这些方向帮助理解词族。fluctuation 有拉丁名词路线；fluency 有拉丁借入与英语派生两种分析。flush 常用动词的远源未定，牌类同花义与法语 flus 的联系也只属可能，本页保留为边界对照。',branches=[['话语和动作顺畅','fluent, fluency, fluently, fluidly'],['流入、流出与汇合','influx, effluent, confluence'],['影响与充足资源','influence, influencer, affluent'],['流体、变化及河流作用','fluid, flux, fluctuate, fluvial']],contrasts='fluid 在物理里不只液体；fluent 也不保证永不出错。affluent 是富裕，effluent 常指废水。fluctuation 是短期起伏，trend 是总体方向。flush 不应整词强归为确定的 fluere 后代。',practice='An influx of visitors can influence a town’s economy. Demand may fluctuate, while fluent communication helps local businesses serve their guests.\n\n游客涌入会影响小镇经济。需求可能波动，而流畅的交流能帮助当地商家服务客人。',words=[w['word'] for w in W]+['superfluous','superfluid'])
