 t=Path(__file__).resolve().parents[1]/'.cache/batch200/drafts/root'
 for k,v in [('roots',[ROOT]),('words',W)]: (t/f'{k}_batch200_root_flu.json').write_text(json.dumps(v,ensure_ascii=False,indent=2))
 print(len(W),'individually authored words')
